import 'package:flutter/material.dart';

enum PatternGroup { reversal, continuation, triangles, candles, context }
enum PatternShape { doubleTop, doubleBottom, tripleTop, tripleBottom, headShoulders, inverseHeadShoulders, roundingTop, roundingBottom, flag, pennant, ascendingTriangle, descendingTriangle, symmetricalTriangle, rectangle, cupHandle, inverseCupHandle, wedge, channel, broadening, pinBar, engulfing, doji, star }

class PatternInfo {
  final String name, english, classification, direction, description, structure, confirmation, notes;
  final PatternGroup group; final PatternShape shape;
  const PatternInfo({required this.name,required this.english,required this.group,required this.shape,required this.classification,required this.direction,required this.description,required this.structure,required this.confirmation,required this.notes});
}

