class PatternLibraryPage extends StatefulWidget {
  const PatternLibraryPage({super.key});
  @override State<PatternLibraryPage> createState()=>_PatternLibraryPageState();
}
class _PatternLibraryPageState extends State<PatternLibraryPage>{
  int filter=0;
  List<PatternInfo> get visible{
    if(filter==0)return patternLibrary;
    const groups=[PatternGroup.reversal,PatternGroup.continuation,PatternGroup.triangles,PatternGroup.candles,PatternGroup.context];
    return patternLibrary.where((p)=>p.group==groups[filter-1]).toList();
  }
  String groupName(PatternGroup g){switch(g){case PatternGroup.reversal:return'انعكاسي';case PatternGroup.continuation:return'استمراري';case PatternGroup.triangles:return'مثلثات';case PatternGroup.candles:return'شموع';case PatternGroup.context:return'قنوات وأوتاد';}}
  @override Widget build(BuildContext context){
    const filters=['الكل','الانعكاسية','الاستمرارية','المثلثات','الشموع','القنوات والأوتاد'];
    return Scaffold(appBar:AppBar(title:const Text('جميع النماذج'),actions:[Center(child:Padding(padding:const EdgeInsetsDirectional.only(end:14),child:Text('\$'+'{visible.length}',style:const TextStyle(color:Colors.cyanAccent,fontWeight:FontWeight.w900))))]),body:ListView(padding:const EdgeInsets.fromLTRB(14,8,14,30),children:[
      Container(padding:const EdgeInsets.all(16),decoration:BoxDecoration(color:const Color(0xFF0D1722),borderRadius:BorderRadius.circular(20),border:Border.all(color:Colors.cyanAccent.withValues(alpha:.55))),child:const Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('مكتبة النماذج الرئيسية',style:TextStyle(fontSize:24,fontWeight:FontWeight.w900)),SizedBox(height:6),Text('لكل نموذج: الاسم، الشكل على الشارت، التصنيف، الاتجاه الصاعد/الهابط/المحايد، الشرح، البنية، والتأكيد.',style:TextStyle(color:Colors.white70,height:1.55))])),
      const SizedBox(height:12),
      SingleChildScrollView(scrollDirection:Axis.horizontal,child:Row(children:[for(int i=0;i<filters.length;i++)Padding(padding:const EdgeInsetsDirectional.only(end:8),child:ChoiceChip(label:Text(filters[i]),selected:filter==i,onSelected:(_)=>setState(()=>filter=i)))])),
      const SizedBox(height:14),
      for(int i=0;i<visible.length;i++)PatternCard(info:visible[i],index:i+1,groupName:groupName(visible[i].group)),
    ]));
  }
}

class PatternCard extends StatelessWidget{
  final PatternInfo info;final int index;final String groupName;
  const PatternCard({super.key,required this.info,required this.index,required this.groupName});
  Color get accent{switch(info.group){case PatternGroup.reversal:return Colors.redAccent;case PatternGroup.continuation:return Colors.greenAccent;case PatternGroup.triangles:return Colors.amber;case PatternGroup.candles:return Colors.cyanAccent;case PatternGroup.context:return Colors.deepPurpleAccent;}}
  @override Widget build(BuildContext context){
    final bull=info.direction.contains('صاعد'),bear=info.direction.contains('هابط');
    final dirColor=bull?Colors.greenAccent:bear?Colors.redAccent:Colors.white70;
    return Card(margin:const EdgeInsets.only(bottom:14),clipBehavior:Clip.antiAlias,child:Padding(padding:const EdgeInsets.all(12),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[
      Row(crossAxisAlignment:CrossAxisAlignment.start,children:[Container(width:38,height:38,alignment:Alignment.center,decoration:BoxDecoration(color:accent.withValues(alpha:.12),borderRadius:BorderRadius.circular(12),border:Border.all(color:accent.withValues(alpha:.55))),child:Text('$index',style:TextStyle(color:accent,fontWeight:FontWeight.w900))),const SizedBox(width:10),Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(info.name,style:const TextStyle(fontSize:19,fontWeight:FontWeight.w900)),const SizedBox(height:2),Text(info.english,style:TextStyle(color:accent,fontWeight:FontWeight.w700))]))]),
      const SizedBox(height:10),SizedBox(height:205,width:double.infinity,child:PatternChart(shape:info.shape,direction:info.direction)),const SizedBox(height:9),
      Wrap(spacing:7,runSpacing:7,children:[BadgeP(text:groupName,color:accent),BadgeP(text:info.classification,color:accent),BadgeP(text:info.direction,color:dirColor)]),
      const SizedBox(height:12),PatternLine(title:'ما هو؟',text:info.description,icon:Icons.info_outline,color:accent),PatternLine(title:'الشكل والبنية',text:info.structure,icon:Icons.account_tree_outlined,color:Colors.white70),PatternLine(title:'التأكيد',text:info.confirmation,icon:Icons.verified_outlined,color:Colors.amber),PatternLine(title:'ملاحظة',text:info.notes,icon:Icons.lightbulb_outline,color:Colors.white54),
    ])));
  }
}
class BadgeP extends StatelessWidget{final String text;final Color color;const BadgeP({super.key,required this.text,required this.color});@override Widget build(BuildContext context)=>Container(padding:const EdgeInsets.symmetric(horizontal:10,vertical:6),decoration:BoxDecoration(color:color.withValues(alpha:.09),borderRadius:BorderRadius.circular(14),border:Border.all(color:color.withValues(alpha:.6))),child:Text(text,style:TextStyle(color:color,fontSize:12,fontWeight:FontWeight.w800)));}
class PatternLine extends StatelessWidget{final String title,text;final IconData icon;final Color color;const PatternLine({super.key,required this.title,required this.text,required this.icon,required this.color});@override Widget build(BuildContext context)=>Padding(padding:const EdgeInsets.only(bottom:9),child:Row(crossAxisAlignment:CrossAxisAlignment.start,children:[Icon(icon,color:color,size:19),const SizedBox(width:7),Expanded(child:RichText(text:TextSpan(style:const TextStyle(color:Colors.white70,height:1.45),children:[TextSpan(text:'$title: ',style:TextStyle(color:color,fontWeight:FontWeight.w900)),TextSpan(text:text)])))]));}

class PatternChart extends StatelessWidget{
  final PatternShape shape;final String direction;
  const PatternChart({super.key,required this.shape,required this.direction});
  @override Widget build(BuildContext context)=>Card(margin:EdgeInsets.zero,color:const Color(0xFF08121C),shape:RoundedRectangleBorder(borderRadius:BorderRadius.circular(16),side:BorderSide(color:Colors.white.withValues(alpha:.08))),child:CustomPaint(painter:PatternChartPainter(shape,direction),child:const SizedBox.expand()));
}
class PatternChartPainter extends CustomPainter{
  final PatternShape shape;final String direction;PatternChartPainter(this.shape,this.direction);
  void path(Canvas c,Paint p,List<Offset> pts){final q=Path()..moveTo(pts.first.dx,pts.first.dy);for(final x in pts.skip(1)){q.lineTo(x.dx,x.dy);}c.drawPath(q,p);}
  void base(Canvas c,Size s){c.drawRRect(RRect.fromRectAndRadius(Offset.zero&s,const Radius.circular(16)),Paint()..color=const Color(0xFF08121C));final g=Paint()..color=Colors.white.withValues(alpha:.045)..strokeWidth=1;for(int i=1;i<5;i++)c.drawLine(Offset(0,s.height*i/5),Offset(s.width,s.height*i/5),g);for(int i=1;i<7;i++)c.drawLine(Offset(s.width*i/7,0),Offset(s.width*i/7,s.height),g);}
